<?php
namespace App\Http\Middleware;use App\Models\Word;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class ReplaceFrontendCopy{public function handle(Request $request,Closure $next):Response{$response=$next($request);if(!$response->isSuccessful()||!str_contains((string)$response->headers->get('Content-Type'),'text/html'))return $response;$copy=Word::with('translations')->whereNotNull('source')->get()->mapWithKeys(fn($w)=>[$this->normalize($w->source)=>$w->title])->filter()->all();if(!$copy)return $response;$parts=preg_split('/(<(?:script|style)\b[^>]*>.*?<\/(?:script|style)>)/is',$response->getContent(),-1,PREG_SPLIT_DELIM_CAPTURE);foreach($parts as $i=>$part){if($i%2)continue;$parts[$i]=preg_replace_callback('/>([^<]+)</u',function($m)use($copy){$normalized=$this->normalize(html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8'));if($normalized===''||!isset($copy[$normalized]))return $m[0];preg_match('/^\s*/u',$m[1],$lead);preg_match('/\s*$/u',$m[1],$tail);return '>'.($lead[0]??'').e($copy[$normalized]).($tail[0]??'').'<';},$part);} $response->setContent(implode('',$parts));return $response;}private function normalize(string $value):string{return preg_replace('/\s+/u',' ',trim($value));}}
